import os
import json
from typing import Any, Dict, List, Optional

import requests


class DocumentLayoutExtractor:
    def __init__(self, api_key: Optional[str] = None, api_base: str = "https://api.veryfi.com/api/v8/partner/documents"):
        self.api_key = api_key or os.getenv("VERYFI_API_KEY")
        self.api_base = api_base.rstrip("/")
        if not self.api_key:
            raise ValueError("VERYFI_API_KEY is required")

    def extract(self, file_path: str) -> Dict[str, Any]:
        with open(file_path, "rb") as f:
            files = {"file": f}
            headers = {
                "Authorization": f"Bearer {self.api_key}",
            }
            response = requests.post(self.api_base, headers=headers, files=files, timeout=120)
            response.raise_for_status()
            data = response.json()

        return self._normalize(data)

    def _normalize(self, data: Dict[str, Any]) -> Dict[str, Any]:
        tables: List[Dict[str, Any]] = []
        for table in self._find_tables(data):
            tables.append(self._normalize_table(table))

        return {
            "source": "veryfi",
            "tables": tables,
        }

    def _find_tables(self, data: Any) -> List[Dict[str, Any]]:
        found: List[Dict[str, Any]] = []

        def walk(node: Any):
            if isinstance(node, dict):
                for key, value in node.items():
                    if key.lower() in {"tables", "table_data"} and isinstance(value, list):
                        for item in value:
                            if isinstance(item, dict):
                                found.append(item)
                    else:
                        walk(value)
            elif isinstance(node, list):
                for item in node:
                    walk(item)

        walk(data)
        return found

    def _normalize_table(self, table: Dict[str, Any]) -> Dict[str, Any]:
        rows = table.get("rows") or table.get("table_rows") or table.get("line_items") or []
        normalized_rows = []

        for row in rows:
            if isinstance(row, dict):
                cells = row.get("cells") or row.get("columns") or row.get("fields") or []
            else:
                cells = row if isinstance(row, list) else []

            normalized_cells = []
            for cell in cells:
                if isinstance(cell, dict):
                    normalized_cells.append(
                        {
                            "text": cell.get("text") or cell.get("value") or cell.get("content") or "",
                            "row_span": cell.get("row_span") or cell.get("rowSpan") or 1,
                            "col_span": cell.get("col_span") or cell.get("colSpan") or 1,
                            "bbox": cell.get("bbox") or cell.get("bounding_box") or cell.get("polygon"),
                        }
                    )
                else:
                    normalized_cells.append(
                        {
                            "text": str(cell),
                            "row_span": 1,
                            "col_span": 1,
                            "bbox": None,
                        }
                    )

            normalized_rows.append({"cells": normalized_cells})

        return {
            "table_id": table.get("id") or table.get("table_id"),
            "page": table.get("page") or table.get("page_num") or table.get("page_number"),
            "rows": normalized_rows,
        }


def extract_table_cells_and_rows(file_path: str, api_key: Optional[str] = None) -> Dict[str, Any]:
    extractor = DocumentLayoutExtractor(api_key=api_key)
    return extractor.extract(file_path)
